 "content": "def transform(grid):
    """Fill zero cells using the value opposite through the grid center."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                out[r][c] = grid[h - 1 - r][w - 1 - c]
    return out
